<script>(()=>{const values=@json($months->pluck('total')->values()),labels=@json($months->pluck('name')->values()),chart=document.getElementById('sales-chart'),axis=document.getElementById('sales-chart-y'),buttons=document.querySelectorAll('[data-chart-type]');let type='bar';const money=value=>`RM ${Number(value).toLocaleString('ms-MY',{maximumFractionDigits:0})}`,max=Math.max(...values,0),ceiling=max?Math.ceil(max/4)*4:100;function render(){axis.innerHTML=[ceiling,ceiling*.75,ceiling*.5,ceiling*.25,0].map(value=>`<span>${money(value)}</span>`).join('');const points=values.map((value,index)=>`${4+(index*92/11)},${92-((value/ceiling)*82)}`).join(' '),grid=[10,31,51,72,92].map(y=>`<line x1="4" y1="${y}" x2="96" y2="${y}"/>`).join('');let visual;if(type==='line'){visual=`<svg viewBox="0 0 100 100" preserveAspectRatio="none" class="line-chart"><g class="chart-grid">${grid}</g><polyline class="chart-area" points="4,92 ${points} 96,92"/><polyline class="chart-line" points="${points}"/>${values.map((value,index)=>{const x=4+(index*92/11),y=92-((value/ceiling)*82);return `<circle cx="${x}" cy="${y}" r="1.35"><title>${labels[index]}: ${money(value)}</title></circle>`}).join('')}</svg>`}else{visual=`<svg viewBox="0 0 100 100" preserveAspectRatio="none" class="bar-chart"><g class="chart-grid">${grid}</g>${values.map((value,index)=>{const height=(value/ceiling)*82,x=5+(index*92/12),y=92-height;return `<rect x="${x}" y="${y}" width="5" height="${height}" rx="1"><title>${labels[index]}: ${money(value)}</title></rect>`}).join('')}</svg>`}chart.innerHTML=`${visual}<div class="sales-chart-labels">${labels.map(label=>`<span>${label.slice(0,3)}</span>`).join('')}</div>`}buttons.forEach(button=>button.addEventListener('click',()=>{type=button.dataset.chartType;buttons.forEach(item=>item.classList.toggle('active',item===button));render()}));document.getElementById('theme-mode').addEventListener('click',()=>setTimeout(render,0));render()})();</script>
